function debounce(fn, wait, options = {}) {
  let timeoutId = null;
  let lastResult;
  let lastArgs;
  let lastContext;
  let lastCallTime = 0;

  const leading = !!options.leading;
  const trailing = !!options.trailing;

  function invoke() {
    const now = Date.now();
    const args = lastArgs;
    const context = lastContext;

    lastResult = fn.apply(context, args);

    lastArgs = null;
    lastContext = null;
    lastCallTime = now;

    timeoutId = null;
    return lastResult;
  }

  function debounced(...args) {
    const now = Date.now();
    lastArgs = args;
    lastContext = this;
    lastCallTime = now;

    const isInvokedNow = leading && !timeoutId;

    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    if (isInvokedNow) {
      invoke();
    }

    timeoutId = setTimeout(() => {
      const shouldInvoke = trailing && (lastArgs !== null);
      if (shouldInvoke) {
        invoke();
      } else {
        timeoutId = null;
      }
    }, wait);

    return lastResult;
  }

  debounced.cancel = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    lastArgs = null;
    lastContext = null;
  };

  debounced.flush = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    if (lastArgs !== null) {
