    const row = [];
    for (let i = 0; i < iterators.length; i++) {
      if (active[i]) {
        const { value, done } = iterators[i].next();
        if (done) {
          active[i] = false;
          row.push(fill);
        } else {
          row.push(value);
        }
      } else {
        row.push(fill);
      }
    }
    yield row;
  }
