function createStore(reducer, initial) {
  let state = initial;
  let listeners = [];
  let isDispatching = false;

  const getState = () => state;

  const dispatch = (action) => {
    if (isDispatching) {
      throw new Error("Reducers, like other state update functions, must be pure. You can't dispatch actions inside reducers.");
    }

    isDispatching = true;
    try {
      const nextState = reducer(state, action);
      state = nextState;

      const listenersSnapshot = [...listeners];
      listenersSnapshot.forEach((listener) => {
        listener();
      });
    } finally {
      isDispatching = false;
    }
    return action;
  };

  const subscribe = (fn) => {
    listeners.push(fn);
    return () => {
      listeners = listeners.filter((l) => l !== fn);
    };
  };

  return {
    getState,
    dispatch,
    subscribe,
  };
}

