export type MatchHandler<T, R> = {
  [K in T['kind']]: (variant: Extract<T, { kind: K }>) => R;
};

export function match<T extends { kind: string }, R>(
  value: T,
  handlers: MatchHandler<T, R>
): R {
  const key = value.kind as keyof MatchHandler<T, R>;
  const handler = handlers[key];
  if (!handler) {
    throw new Error(`No handler for variant: ${key}`);
  }
  return handler(value as any);
}
