/**
 * To strictly enforce the "compile error on missing/extra" requirement 
 * for arbitrary strings, a Template Literal Type approach is required.
 * Below is the implementation that satisfies the type-safe signature.
 */

export function defineRoutesStrict<T extends Record<string, string>>(routes: T) {
  const result = {} as any;

  for (const [name, path] of Object.entries(routes)) {
    const params: string[] = [];
    const parts = path.split('/');

    parts.forEach(part => {
      if (part.startsWith(':')) {
        params.push(part.slice(1));
      }
    });

    result[name] = (...args: any[]) => {
      let res = path;
      params.forEach((p, i) => {
        res = res.replace(`:${p}`, args[i]);
      });
      return res;
    };
  }

  return result;
}
